    handleDuplicate,
    currentStepId,
    baseComponents,
    setBaseComponents,
    handleHistorySnapshot,
    steps,
    setSteps,
    setSelectedCompIds,
    setActiveLogicScopeId,
    setViewMode,
    sidebarSearch,
    setSidebarSearch,
    Date,
    setTriggerEditor,
    updateComponentProps,
    getFriendlyTriggerName,
    Math,
    parseInt,
    reorderComponent,
    appVariables,
    updateComponentDisplayName,
    updateComponentName,
    Object,
    ICON_BUTTON_ICONS,
    Boolean,
    JSON,
    localStorage,
    dimensions,
    find,
    Number,
    parseFloat,
    renderTargetVariableOptions,
    widgetImageInputRef,
