    isUploadingImage,
    widgetPdfInputRef,
    handleLocalPdfUpload,
    isUploadingPdf,
    undefined,
    source,
    volume,
    builderCameras,
    type,
    url,
    settings,
    regions,
    length,
    timeInterval,
    enabled,
    timerAlwaysFires,
    refreshTime,
    distanceInterval,
    providerLocked,
    sensitivity,
    minimumInterval,
    legacyMode,
    useExternalScanner,
    readMode,
    textToWrite,
    stopDetectionTimeout,
    strideLength,
    keepRunningWhenOnPause,
    projectID,
    redisServer,
    redisPort,
    token,
    useSSL,
    defaultScope,
    sourceFile,
    readPermission,
    writePermission,
    applicationName,
    spreadsheetID,
    credentialsJson,
    namespace,
    serviceURL,
    description,
    gridEnabled,
    legendEnabled,
    lineType,
    pointShape,
    model,
    extend,
    axesTextColor,
    color,
    center,
    zoomLevel,
    mapType,
    showUser,
    showZoom,
    latitude,
    longitude,
    radius,
    northLatitude,
    southLatitude,
    eastLongitude,
    westLongitude,
    apiKey,
    transportationMethod,
    title,
    strokeColor,
    renderDataSourceSection,
    INPUT_WIDGET_TYPES_WITH_DATASOURCE,
    recordPlaceholders,
    savedAnalyses,
    iotConfig,
    String,
    tables,
    columns,
    map,
    aggregations,
    queries,
    deleteComponent,
    currentStep,
    updateCurrentStep,
    orientation,
    backgroundColor,
    backgroundImage,
    alignHorizontal,
    alignVertical,
    scrollable,
    currentStepCycleMinutes,
    updateCurrentStepCycleTime,
    currentStepCycleRemainSeconds,
    formatTime,
    currentStepCycleSeconds,
    isFormStep,
    currentStepFormSubmit,
    updateCurrentStepFormSubmit,
    getStepFormComponents,
    buildAutoTableMappingsFromComponents,
    addStepTriggerTemplate,
    triggers,
    updateStepTriggers,
    appMeta,
    handlePublish,
    handleRequestApproval,
    handleApproveApp,
    appBackgroundColor,
    setAppBackgroundColor,
    setAppThemeMode,
    appThemeMode,
    setScalingMode,
    scalingMode,
    setVariableEditor,
    setAppFunctions,
    appFunctions,
    setFunctionEditor,
    appCompletions,
    setSelectedCompletion,
    setIsCompletionModalOpen,
    appTriggers,
    setAppTriggers,
    previewDevice,
    handleDeviceChange,
    DEVICE_PRESETS,
    materialId,
    setMaterialId,
    productImage,
    setProductImage,
    setIsUploadingImage,
    Promise,
    FileReader,
    Error,
    isSupabaseReady,
    currentAppId,
    uploadManualImage,
    alert,
    message
