                                                                            <input type="number" min="0" max="100" value={selectedComp.props.volume ?? 50} onChange={(e) => updateComponentProps(selectedComp.id, { volume: parseInt(e.target.value) })} style={{ width: '100%', padding: '6px', border: '1px solid var(--border-primary)', borderRadius: '4px' }} />
